/**
 * Ground truth for a compaction summary, generated by code.
 *
 * The summary is written by a model, and a model writing about a transcript it
 * only saw as prose will fill gaps. After one compaction Claude Sonnet called
 * `str_replace` — a tool that has never existed in this repo — eight times,
 * because the prose it was given never contained a real tool name and it
 * guessed a plausible one (SHO-122, from the prod proxy mining run).
 *
 * So the facts are not left to the summarizer. They are derived from the
 * compacted messages themselves and appended to the summary by `applyCompaction`
 * under a marker that says so. Even a summary that says nothing but "I did
 * some stuff." still states the files that were edited and the exact tool
 * names the model will be offered next turn.
 *
 * Derived from the messages, deliberately not from `FileStateCache`: its
 * `editedThisTurn` is reset at every turn start, so at pre-turn compaction
 * time it is empty — exactly when this block is written.
 */

import type { AssistantMessage, Message, TextContent, ToolCall, ToolResultMessage } from '@mariozechner/pi-ai'

/** Marks the block as machine-written, so nobody — human or model — edits it by hand. */
export const GROUND_TRUTH_MARKER = '<!-- ground truth, generated -->'

/** Tools that name a file in their arguments. */
const READ_TOOLS = new Set(['read_file'])
const EDIT_TOOLS = new Set(['edit_file', 'write_file', 'multi_edit', 'apply_patch'])

/** Argument keys that carry a path, in the order the tools use them. */
const PATH_KEYS = ['path', 'file_path', 'target_file', 'filePath'] as const

export interface FileTouched {
  path: string
  read: boolean
  edited: boolean
}

export interface CompactionFacts {
  files: FileTouched[]
  tools: Array<{ name: string; count: number }>
  /** First line of the most recent failing tool result, if any. */
  lastError: string | null
}

function textOf(msg: Message): string {
  if (msg.role !== 'toolResult') return ''
  return (msg as ToolResultMessage).content
    .filter((c): c is TextContent => c.type === 'text')
    .map((c) => c.text)
    .join('')
}

function pathOf(args: Record<string, any> | undefined): string | null {
  if (!args) return null
  for (const key of PATH_KEYS) {
    const value = args[key]
    if (typeof value === 'string' && value.trim()) return value.trim()
  }
  return null
}

/** Every file a compaction touched, every tool it called, and the last error seen. */
export function collectCompactionFacts(messages: readonly Message[]): CompactionFacts {
  const files = new Map<string, FileTouched>()
  const tools = new Map<string, number>()
  let lastError: string | null = null

  const touch = (path: string, kind: 'read' | 'edited') => {
    const entry = files.get(path) ?? { path, read: false, edited: false }
    entry[kind] = true
    files.set(path, entry)
  }

  for (const msg of messages) {
    if (msg.role === 'assistant') {
      const content = (msg as AssistantMessage).content
      if (!Array.isArray(content)) continue
      for (const block of content) {
        if (block?.type !== 'toolCall') continue
        const call = block as ToolCall
        tools.set(call.name, (tools.get(call.name) ?? 0) + 1)
        const path = pathOf(call.arguments as Record<string, any>)
        if (!path) continue
        if (READ_TOOLS.has(call.name)) touch(path, 'read')
        else if (EDIT_TOOLS.has(call.name)) touch(path, 'edited')
      }
      continue
    }
    if (msg.role === 'toolResult' && (msg as ToolResultMessage).isError) {
      const firstLine = textOf(msg).split('\n').map((l) => l.trim()).find(Boolean)
      if (firstLine) lastError = firstLine
    }
  }

  return {
    files: [...files.values()].sort((a, b) => a.path.localeCompare(b.path)),
    tools: [...tools.entries()]
      .map(([name, count]) => ({ name, count }))
      .sort((a, b) => b.count - a.count || a.name.localeCompare(b.name)),
    lastError,
  }
}

/**
 * The block appended to a summary. `## Files touched` and `## Tools used` are
 * always present, even when empty: a model that reads "Tools used: (none)"
 * knows the turn made no tool calls, where a missing section reads as unknown.
 * An edited file is listed even when it was never read.
 */
export function renderCompactionFacts(facts: CompactionFacts): string {
  const lines: string[] = [GROUND_TRUTH_MARKER, '## Files touched']
  if (facts.files.length === 0) {
    lines.push('- (none)')
  } else {
    for (const file of facts.files) {
      const marks: string[] = []
      if (file.edited) marks.push('edited')
      if (file.read) marks.push('read')
      lines.push(`- \`${file.path}\` — ${marks.join(', ')}`)
    }
  }

  lines.push('## Tools used')
  if (facts.tools.length === 0) {
    lines.push('- (none)')
  } else {
    for (const tool of facts.tools) lines.push(`- \`${tool.name}\` ×${tool.count}`)
  }

  lines.push('## Current state')
  lines.push(
    facts.lastError
      ? `- Last error seen: ${facts.lastError}`
      : '- No failing tool result in the compacted range.',
  )

  return lines.join('\n')
}

/** Facts for `messages`, rendered — the string `applyCompaction` appends. */
export function buildCompactionFactsBlock(messages: readonly Message[]): string {
  return renderCompactionFacts(collectCompactionFacts(messages))
}
